// VoiceEdit against the clients' shared fixture (test/fixtures/voice-edits.json, its edits generated by the hub).
// Compiled with Backplane/VoiceEdit.swift alone, outside the app: scripts/mobile/ios-voice-edit-test.sh.
import Foundation

let path = CommandLine.arguments.dropFirst().first ?? "test/fixtures/voice-edits.json"
let f = try! JSONSerialization.jsonObject(with: Data(contentsOf: URL(fileURLWithPath: path))) as! [String: Any]
var failed = 0, passed = 0
func check(_ ok: Bool, _ name: Any?, _ got: Any) { if ok { passed += 1 } else { failed += 1; print("FAIL \(name ?? "?"): got \(got)") } }
func int(_ v: Any?) -> Int { (v as? NSNumber)?.intValue ?? 0 }
func str(_ v: Any?) -> String { v as? String ?? "" }

for c in f["edits"] as! [[String: Any]] {
    let w = c["want"] as! [String: Any]
    var text = str(c["draft"]), mark = int(c["caret"]), caret = int(c["caret"])
    for e in w["edits"] as! [[String: Any]] {
        let r = VoiceEdit.apply(text, mark: mark, del: int(e["del"]), ins: str(e["ins"]), adv: int(e["adv"]), to: int(e["to"]))
        (text, mark, caret) = (r.text, r.mark, r.caret)
    }
    check(text == str(w["text"]) && mark == int(w["mark"]) && caret == int(w["caret"]), c["name"], (text, mark, caret))
}
for c in f["apply"] as! [[String: Any]] {
    let e = c["edit"] as! [String: Any], w = c["want"] as! [String: Any]
    let r = VoiceEdit.apply(str(c["text"]), mark: int(c["mark"]), del: int(e["del"]), ins: str(e["ins"]), adv: int(e["adv"]), to: int(e["to"]), back: int(e["back"]))
    check(r.text == str(w["text"]) && r.mark == int(w["mark"]) && r.caret == int(w["caret"]), c["name"], r)
}
do { let u = VoiceEdit.undo("Buy milk.", "And eggs.", mark: 9); check(u.text == "Buy milk. And eggs." && u.mark == 19, "undo", u) }
for c in f["shift"] as! [[String: Any]] {
    let m = VoiceEdit.shift(str(c["old"]), str(c["new"]), mark: int(c["mark"]))
    check(m == int(c["want"]), c["name"], m)
}
// the text field counts UTF-16; the hub counts characters
check(VoiceEdit.utf16("é😀x", caret: 2) == 3 && VoiceEdit.chars("é😀x", utf16: 3) == 2, "utf16 <-> characters", "")
print("voice edits: \(passed) passed, \(failed) failed")
exit(failed == 0 ? 0 : 1)
